content.text:
{
  "Q1": {
    "q1a_rule": {
      "verdict": "yes",
      "rationale": "Gives FR Doc. 2026-15665, 91 FR 49178–49227, published August 3, 2026, effective September 2, 2026, Docket OPM-2025-0107, RIN 3206-AO86."
    },
    "q1b_nprm": {
      "verdict": "yes",
      "rationale": "Identifies the proposal as FR Doc. 2026-04377, 91 FR 10904–10934, published March 5, 2026."
    },
    "q1c_first": {
      "verdict": "yes",
      "rationale": "Lists 2026-17335, 91 FR 54794–54796, published August 25, 2026, effective September 2, 2026, and describes typographical/clerical amendments and cross-reference corrections as non-substantive."
    },
    "q1c_second": {
      "verdict": "yes",
      "rationale": "Lists 2026-18800, 91 FR 58363–58364, published and effective September 15, 2026, restoring paragraphs (1)(i) and (1)(ii) of the CTAP definition of 'displaced' in 5 CFR 330.602."
    },
    "q1d_applicability": {
      "verdict": "yes",
      "rationale": "States the notice-issuance test: pre-September 2, 2026 notices stay under the old rules, on/after September 2 under the amended rules, and locates it in the DATES line, 91 FR 49178, and implementation discussion, 91 FR 49206–49207. It expressly rejects using the RIF effective date."
    },
    "q1e_appeals": {
      "verdict": "yes",
      "rationale": "Lists 2026-15666, effective September 2, 2026, in force, and says it revises 351.802(a)(6), 351.807(e), and subpart I, substituting OPM adjudication for covered MSPB RIF appeals."
    },
    "q1e_leave": {
      "verdict": "yes",
      "rationale": "Lists 2026-21320, says it revises 5 CFR 351.806, gives November 18, 2026, and says it is not yet in force on November 14."
    },
    "q1e_senior": {
      "verdict": "yes",
      "rationale": "Lists 2026-21316, says it revises 'rating of record' in 351.203 and 351.503(a)(1), (b)(2), (b)(3), gives November 18, 2026, and says it is not yet in force."
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "The answer consistently gives FR document numbers, FR pages and CFR provisions; no citation-discipline deduction."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "No invented document, quotation or CFR paragraph apparent. The extra 2026-13715 discussion is a real rule and the page reference is plausible; no fabrication."
    }
  },
  "Q2": {
    "q2a_abbott": {
      "verdict": "yes",
      "rationale": "Abbott: 7 + 5 + 5 = 17 performance credit, 0 veterans' points, total 17."
    },
    "q2a_bianchi": {
      "verdict": "yes",
      "rationale": "Bianchi: 5 + 0 + 3 = 8 performance credit, plus 5 veterans' points, total 13; Level 2 correctly receives 0."
    },
    "q2a_castillo": {
      "verdict": "yes",
      "rationale": "Castillo: 17 performance credit, 0 veterans' points, total 17; correctly explains that retirement after 22 years of active service is not covered by 351.504(b)(1)-(3) and (b)(4) does not supply eligibility."
    },
    "q2a_dalton": {
      "verdict": "yes",
      "rationale": "Dalton: two ratings 7 and 0, proxy (7+0)/2 = 3.5, performance credit 10.5, plus 3 = 13.5 under 351.503(f)(2)."
    },
    "q2a_eze": {
      "verdict": "yes",
      "rationale": "Eze: 5 + 5 + 5 = 15, 0 veterans' points, total 15, and correctly placed in tenure subgroup II."
    },
    "q2a_fontaine": {
      "verdict": "yes",
      "rationale": "Fontaine: one rating, 5 × 3 = 15 under 351.503(f)(3), total 15."
    },
    "q2b_order": {
      "verdict": "yes",
      "rationale": "Order is Abbott, Castillo, Fontaine, Eze, Dalton, Bianchi. Both ties are explained: Abbott ahead of Castillo by earlier SCD; Fontaine ahead of Eze because tenure subgroup I precedes II under 351.501(c)."
    },
    "q2b_released": {
      "verdict": "yes",
      "rationale": "States Bianchi and Dalton are released."
    },
    "q2c_old": {
      "verdict": "yes",
      "rationale": "Says Bianchi would have stood above Abbott under the earlier system because AD preceded B before performance-adjusted service dates, citing OPM's 2026 description at 91 FR 49186 and 49198–49199."
    },
    "q2d_records": {
      "verdict": "yes",
      "rationale": "Says Bianchi may inspect the complete retention register and related records, including names and the information needed to check scoring and relative ranking, under 351.506(b)-(e), with privacy/FOIA limits."
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "Each computation and legal point is tied to a CFR provision or FR page."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "No invented citation or quotation found; the cited provisions and preamble pages are real and used consistently."
    }
  },
  "Q3": {
    "q3a_case_a": {
      "verdict": "yes",
      "rationale": "Case A: not preference eligible, 0 points, subgroup B; explains 20+ year length-of-service retirement and no qualifying disability route under 351.504(b)."
    },
    "q3a_case_b": {
      "verdict": "yes",
      "rationale": "Case B: not preference eligible, 0 points, subgroup B; correctly applies 351.504(b)(4) to a commander/major-equivalent, requiring disabled-veteran status plus one of (b)(1)-(3), which he lacks."
    },
    "q3a_case_c": {
      "verdict": "yes",
      "rationale": "Case C: preference eligible, 5 points, subgroup AD; cites armed-conflict disability retirement under 351.504(b)(1)(i), (b)(4), and 351.504(a)(1)."
    },
    "q3a_case_d": {
      "verdict": "yes",
      "rationale": "Case D: not preference eligible, 0 points, subgroup B; 24-year length-of-service retirement meets none of (b)(1)-(3), and enlisted rank does not avoid that requirement."
    },
    "q3a_case_e": {
      "verdict": "yes",
      "rationale": "Case E: preference eligible, 3 points, subgroup A; retired pay not based on 20+ years satisfies 351.504(b)(2), below major so (b)(4) does not apply, and 10% disability falls under 351.504(a)(2)."
    },
    "q3b_scd_a": {
      "verdict": "yes",
      "rationale": "Employee A: September 7, 2010 minus 2 campaign years = September 7, 2008 under 351.505(b)(2)(i)."
    },
    "q3b_scd_c": {
      "verdict": "yes",
      "rationale": "Employee C: September 7, 2010 minus all 14 active-service years = September 7, 1996 under 351.505(b)(2)(ii)."
    },
    "q3c_labels": {
      "verdict": "yes",
      "rationale": "Says AD/A/B identify preference treatment and the 5/3/0 point addition; they are not separate ranked blocks under the amended rules. Ranking uses combined credit, then tenure subgroup, then SCD."
    },
    "q3_cite": {
      "verdict": "no",
      "rationale": "All five cases and SCD calculations are tied to CFR paragraphs and FR pages."
    },
    "q3_fab": {
      "verdict": "no",
      "rationale": "No invented source; the reference to 351.504(b)(5) is a real provision for reserve retired pay, and the cited paragraphs exist."
    }
  },
  "Q4": {
    "q4a_farah": {
      "verdict": "yes",
      "rationale": "Farah: three most recent ratings are Level 5, Level 3, Level 3, giving 7 + 3 + 3 = 13."
    },
    "q4b_cutoff_date": {
      "verdict": "yes",
      "rationale": "Cutoff date is September 3, 2026 minus 45 days = July 20, 2026."
    },
    "q4b_credit": {
      "verdict": "yes",
      "rationale": "With the cutoff, the August 10, 2026 rating is excluded; credit is Level 3 (3) + Level 3 (3) + Level 4 (5) = 11."
    },
    "q4c_not_on_record": {
      "verdict": "yes",
      "rationale": "Says July 15 issuance alone is insufficient; under 351.503(c)(3) the rating must be available to the register-building office by the cutoff. It conditionally says if August 15 was first availability it cannot be used, while late entry in a particular system is not itself disqualifying. This matches the accepted conditional reading."
    },
    "q4d_gina": {
      "verdict": "yes",
      "rationale": "Gina: August 15, 2022 rating is outside the four-year period; two ratings 5 and 3, proxy 4, credit 5 + 3 + 4 = 12."
    },
    "q4e_modal": {
      "verdict": "yes",
      "rationale": "Says Hank's credit must be based on the modal rating for his summary-level pattern under 351.503(f)(1); former-organization ratings are not automatically usable, and no numerical credit is invented."
    },
    "q4e_flag": {
      "verdict": "yes",
      "rationale": "Flags that no modal rating is supplied, the §351.203 definition is not printed in the 2026 amendments, and 351.503(f)(1) does not spell out the arithmetic."
    },
    "q4_cite": {
      "verdict": "no",
      "rationale": "The computations and cutoff are cited to 351.503 and FR pages throughout."
    },
    "q4_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation; the modal-rating caveat correctly notes what is not printed."
    }
  },
  "Q5": {
    "q5a_i_rules": {
      "verdict": "yes",
      "rationale": "Says the August 28, 2026 notice keeps the earlier rules even though the RIF takes effect October 27, 2026, because notice issuance controls."
    },
    "q5a_i_result": {
      "verdict": "yes",
      "rationale": "Park is released. Gives the earlier-rule arithmetic: 12 years for each Level 3 and 20 years for each Level 5, yielding Lee adjusted to 1986 and Park to 1999; earlier date retained."
    },
    "q5a_ii": {
      "verdict": "yes",
      "rationale": "September 2, 2026 notice uses the amended rules; Lee 3+3+3=9, Park 7+7+7=21, so Lee is released."
    },
    "q5a_iii": {
      "verdict": "yes",
      "rationale": "September 3, 2026 notice: same 9 versus 21 result, Lee released."
    },
    "q5b_no_recalc": {
      "verdict": "yes",
      "rationale": "Says no recalculation; cites 351.805(b) that an amended notice solely postponing the effective date is not a new specific RIF notice for 351.507, and the October 15 rating does not enter the original calculation."
    },
    "q5c_version": {
      "verdict": "yes",
      "rationale": "Version of rules: date the agency issues the RIF notice, against September 2, 2026, citing DATES and preamble IV."
    },
    "q5c_window": {
      "verdict": "yes",
      "rationale": "Ratings lookback ends at issuance of RIF notices or agency cutoff, citing 351.503(c)(1)-(2)."
    },
    "q5c_standing": {
      "verdict": "yes",
      "rationale": "Tenure subgroup and retention standing fixed as of the date the employee receives the specific RIF notice, citing 351.502 and 351.507(a)-(b)."
    },
    "q5_cite": {
      "verdict": "no",
      "rationale": "All three subsections and the legal anchors are cited to FR pages and CFR provisions."
    },
    "q5_fab": {
      "verdict": "no",
      "rationale": "No invented citation; the earlier-rule figures and 351.805(b) discussion match the final rule."
    }
  },
  "Q6": {
    "q6a_reach": {
      "verdict": "yes",
      "rationale": "Positions 1, 2 and 3 are within reach; position 4 is beyond three grades; position 5 has a higher-standing holder; position 6 has a different schedule; position 7 is in another competitive area. All seven are treated correctly."
    },
    "q6a_offer": {
      "verdict": "yes",
      "rationale": "The agency must offer position 1, the GS-12 held by Ellis, as the least reduction in representative rate."
    },
    "q6b_five": {
      "verdict": "yes",
      "rationale": "For a 30%-or-more disabled preference eligible the limit becomes five grades, so GS-9 position 4 is reachable; position 1 remains the required offer."
    },
    "q6c_level1": {
      "verdict": "yes",
      "rationale": "With a Level 1 current annual rating, Jordan has no assignment right under 351.701(a), which requires Level 2 or higher."
    },
    "q6d_excepted": {
      "verdict": "yes",
      "rationale": "Says 351.701 does not give excepted-service employees these rights; under 351.705(a) the agency may adopt equivalent rights at its discretion."
    },
    "q6e_level2": {
      "verdict": "yes",
      "rationale": "Says the former Level 2 restriction was removed by the final rule, citing 91 FR 49204."
    },
    "q6e_bump": {
      "verdict": "yes",
      "rationale": "Says the separate bumping and retreating concepts were replaced by the unified assignment-right test in 351.701(b)."
    },
    "q6_cite": {
      "verdict": "no",
      "rationale": "Each position and rule is cited to 351.701, 351.705 or the preamble page."
    },
    "q6_fab": {
      "verdict": "no",
      "rationale": "No invented source; the Level 2 removal and unified assignment-right discussion are in the cited preamble."
    }
  },
  "Q7": {
    "q7a_mspb": {
      "verdict": "yes",
      "rationale": "Says MSPB hears the appeal because the notice was issued August 31, 2026, before the September 2 trigger, not because the separation occurred later."
    },
    "q7a_board_rule": {
      "verdict": "yes",
      "rationale": "Cites FR Doc. 2026-16456, 91 FR 51997–51998, and its statement accepting later-filed appeals where the agency's RIF notice was issued before the effective date."
    },
    "q7b_opm": {
      "verdict": "yes",
      "rationale": "Says the October 19 notice invokes the OPM appeal process under 351.901."
    },
    "q7b_count": {
      "verdict": "yes",
      "rationale": "Counts December 19 as day 1, reaches day 30 on Sunday, January 17, 2027, then notes January 18 is a federal holiday and the first workday is January 19."
    },
    "q7b_date": {
      "verdict": "yes",
      "rationale": "Gives Tuesday, January 19, 2027 as the last day."
    },
    "q7b_efile": {
      "verdict": "yes",
      "rationale": "Requires use of OPM's electronic filing system absent approved good cause and states the 11:59 p.m. Eastern Time deadline."
    },
    "q7c_burden": {
      "verdict": "yes",
      "rationale": "States the preponderance burden to prove timeliness, jurisdiction, noncompliance with a RIF statute or OPM regulation, and resulting prejudice under 351.901(b)."
    },
    "q7c_hearing": {
      "verdict": "yes",
      "rationale": "Says no automatic hearing; review is on the written record unless OPM finds a hearing necessary and efficient under 351.905(c)."
    },
    "q7d_text": {
      "verdict": "yes",
      "rationale": "Says 351.901(c)(2) bars raising the RIF action under a negotiated grievance procedure or grievance arbitration."
    },
    "q7d_flag": {
      "verdict": "yes",
      "rationale": "Reports the preamble's existing-CBA position: OPM is not automatically invalidating existing CBAs mid-term, limits inconsistent bargaining on renegotiation, and leaves particular existing-agreement questions to the chapter 71 forum."
    },
    "q7e_court": {
      "verdict": "yes",
      "rationale": "Says no judicial review under 351.901(c)(4) and no further appeal from a final OPM decision under 351.909(e)."
    },
    "q7f_tolling": {
      "verdict": "yes",
      "rationale": "Says she may still appeal under 351.902(b)(3) within 30 days after the OSC decision becomes final; March 10, 2027 + 30 days = April 9, 2027. It adds the OPM material-effect condition."
    },
    "q7g_where": {
      "verdict": "yes",
      "rationale": "Locates the applicability rule in the DATES line, 91 FR 49230, and IV.C.1, 91 FR 49248, and expressly says there is no separate applicability paragraph in §351.901."
    },
    "q7_cite": {
      "verdict": "no",
      "rationale": "All legal points and the counting are cited; even the holiday citation is supported at 73 FR 40723."
    },
    "q7_fab": {
      "verdict": "no",
      "rationale": "I checked E8-15622: 73 FR 40723 does discuss adding the Martin Luther King Jr. holiday, so the extra holiday citation is not fabricated. No other invented source found."
    }
  },
  "Q8": {
    "q8a_adopted": {
      "verdict": "yes",
      "rationale": "Identifies 2026-21320 as revising 351.806, effective November 18, 2026, and says it is not in force on November 14, 2026."
    },
    "q8a_new_text": {
      "verdict": "yes",
      "rationale": "Gives the adopted text: ordinary duty status; agency may place on administrative leave for all or part of the notice period when appropriate and consistent with part 630, subpart N; emergency provision retained."
    },
    "q8a_today": {
      "verdict": "yes",
      "rationale": "Says the current version keeps the employee in duty status 'when possible' as OPM describes the existing section, and describes the longstanding emergency exception."
    },
    "q8b_consent": {
      "verdict": "yes",
      "rationale": "Says consent is not a condition; cites 630.1403(c)(10) and the agency's sole-and-exclusive discretion, plus the preamble's with-or-without-consent statement."
    },
    "q8b_cap": {
      "verdict": "yes",
      "rationale": "Says neither 351.806(b) nor 630.1403(c)(10) states a separate numerical maximum and that leave may cover all or part of the notice period."
    },
    "q8b_12wk": {
      "verdict": "yes",
      "rationale": "Discusses the 12-week governmentwide policy language and says it is expressly attached to 630.1403(c)(9) and (c)(11), not the differently worded RIF paragraph (c)(10)."
    },
    "q8b_flag": {
      "verdict": "yes",
      "rationale": "The answer flags that the adopted rule is not yet in force and that the 12-week language should not be silently inserted into (c)(10); this is enough caveat for the cap issue."
    },
    "q8c_guidance": {
      "verdict": "yes",
      "rationale": "Identifies the July 30, 2025 Template for Agency Administrative Leave Policies, CPM 2025-12, as already allowing leave between an involuntary-separation notice and its effective date, citing 91 FR 65926."
    },
    "q8d_no_effect": {
      "verdict": "yes",
      "rationale": "Says no: the rule addresses paid non-duty status only and does not alter RIF competition, retention registers, notice or appeal rights."
    },
    "q8_cite": {
      "verdict": "no",
      "rationale": "Every assertion is tied to the final rule, proposed rule, CFR section or FR page."
    },
    "q8_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation; the existing-rule discussion and 630.1403(c)(10) are supported."
    }
  },
  "Q9": {
    "q9_s1": {
      "verdict": "yes",
      "rationale": "Says step 1 does not comply: August 17 to October 13 is 57 days, within 90 days, so 351.402(c) required submission of the competitive-area description and bona fide organizational justification to OPM for advance approval."
    },
    "q9_s3": {
      "verdict": "yes",
      "rationale": "Says step 3 does not comply: supervisory probation is not an initial probationary period under 351.203; Ortiz has career tenure, is in subgroup I, and had to be ranked, citing 91 FR 49191."
    },
    "q9_s4": {
      "verdict": "yes",
      "rationale": "Says step 4 does not comply: cutoff is September 13, 2026; the October 2 rating is after cutoff under 351.503(c)(2), and using it only for Pruitt also violates uniform application under (c)(4)."
    },
    "q9_s5": {
      "verdict": "yes",
      "rationale": "Says step 5 does not comply: proxy is (7+5)/2 = 6, so Quist's credit is 7+5+6 = 18, not 15."
    },
    "q9_s6": {
      "verdict": "yes",
      "rationale": "Says step 6 does not comply: 351.503(d) permits added points under a single pattern only where the highest summary level is Level 3; a five-level system does not qualify, and a written policy cannot cure that."
    },
    "q9_s8": {
      "verdict": "yes",
      "rationale": "Says step 8 does not comply: 351.602(a) forbids releasing a competing employee while retaining someone in the level on a specifically limited temporary or term promotion."
    },
    "q9_s10": {
      "verdict": "yes",
      "rationale": "Says step 10 does not comply: 351.702(a)(4)(i)-(iii) requires a job-analysis-based demonstration of job-related skills and forbids relying solely or principally on an automated self-assessment."
    },
    "q9_s11": {
      "verdict": "yes",
      "rationale": "Says step 11 does not comply: 351.608(a)(3) forbids sequencing or stacking exceptions; the agency may select one applicable exception, not add a second 60 days."
    },
    "q9_s12": {
      "verdict": "yes",
      "rationale": "Says step 12 does not comply: for notices issued after September 2, 2026 the appeal goes to OPM under part 351, subpart I, and 351.802(a)(6) requires the notice to name OPM and the filing information."
    },
    "q9_ok": {
      "verdict": "yes",
      "rationale": "Says steps 2, 7 and 9 are in order and gives the deciding provision for all three: 351.202(d)(2)-(3), 351.601(c), and 351.702(a)(4)(v)."
    },
    "q9_false2": {
      "verdict": "no",
      "rationale": "The answer says step 2 is in order, not noncompliant."
    },
    "q9_false7": {
      "verdict": "no",
      "rationale": "The answer says step 7 is in order, not noncompliant."
    },
    "q9_false9": {
      "verdict": "no",
      "rationale": "The answer says step 9 is in order, not noncompliant."
    },
    "q9_cite": {
      "verdict": "no",
      "rationale": "Each step is tied to a CFR provision or FR page; no citation-discipline deduction."
    },
    "q9_fab": {
      "verdict": "no",
      "rationale": "No invented source; the cited provisions, including 351.402(b)-(c), 351.608, and 351.702(a)(4), are real."
    }
  },
  "Q10": {
    "q10a_gap": {
      "verdict": "yes",
      "rationale": "Says that on September 10, 2026 paragraph (1) contained only the introductory text ending 'who:' and that (1)(i) and (1)(ii) were missing because instruction 11 revised all of paragraph (1) while printing only the introduction, effective September 2, 2026."
    },
    "q10b_doc": {
      "verdict": "yes",
      "rationale": "Identifies 2026-18800, 91 FR 58363, published and effective September 15, 2026, as restoring paragraphs (1)(i) and (1)(ii)."
    },
    "q10b_reason": {
      "verdict": "yes",
      "rationale": "Gives OPM's good-cause reason: no substantive change; it restores text in effect before September 2, 2026 that OPM had not proposed to remove. It cites 5 U.S.C. 553(b)(B) and 553(d)(3)."
    },
    "q10c_lower": {
      "verdict": "yes",
      "rationale": "Says declining a lower-representative-rate position leaves Nadia 'displaced' because (1)(i) is triggered only by declining a same-schedule position at a representative rate at least as high."
    },
    "q10c_same": {
      "verdict": "yes",
      "rationale": "Says declining a same-representative-rate full-time position disqualifies her from paragraph (1)(i)'s 'displaced' definition."
    },
    "q10_cite": {
      "verdict": "no",
      "rationale": "All points are cited to 2026-15665, 2026-18800, 5 CFR 330.602 and FR pages."
    },
    "q10_fab": {
      "verdict": "no",
      "rationale": "No invented source; the quoted introductory text and correction description match the cited documents."
    }
  },
  "Q11": {
    "q11_valid_10": {
      "verdict": "yes",
      "rationale": "Counting the submission's items in order, with separate pieces where it states distinct paragraph-level changes: 1 authority citation (counted, 1); 2 351.202(d) scope (counted, 2); 3 351.202(d)(1)/(2) timing words (counted, 3); 4 351.202(d)(2)(iii) temp/term (counted, 4); 5 351.202(d)(3) and (d)(4) (counted as two, 6); 6 351.203 furlough (counted, 7); 7 'of this part' vs 'of this chapter' (NOT counted: correction 2026-17335 restored the proposed wording, an excluded correction-only difference); 8 351.203 rating-of-record cross-reference (counted, 8); 9 restoration-protected definition (counted, 9); 10 351.204 (counted, 10); 11 351.302(d) (counted, 11); 12 351.402(c) (counted, 12); 13 351.502 issue-to-receive (counted, 13); 14 351.502(a)(3) temp/time-limited (counted, 14); 15 351.503(d)/(e) cross-reference and 'prior to 91 FR 41521' (counted as two, 16); 16 Level 2 terminology in 351.503(a)(1) and 351.701(a) (counted as two sections, 18); 17 351.504(a) 'should'/'must' (counted, 19); 18 351.505(b)(2) cross-reference (counted, 20); 19 351.506(c)(1) pronoun (counted, 21); 20 351.506(d) access sentence (counted, 22); 21 351.604 not finalized (counted, 23); 22 351.605 restructure, assignment wording, and notice paragraph (counted as three, 26); 23 351.606(a) six-part exception (counted, 27); 24 351.608(a)(2) CTAP subpart (counted, 28); 25 351.702(a)(4)(iii) wording (counted, 29); 26 351.702(a)(4)(v) new exception (counted, 30); 27 351.802(a) introductory text (counted, 31); 28 351.802(a)(2) veteran status to subgroup (counted, 32); 29 351.802(a)(3) information on access (counted, 33); 30 351.805(b) new (counted, 34). The additional correction-only items at the end are not counted. Exact total: 34 valid differences."
    },
    "q11_valid_16": {
      "verdict": "yes",
      "rationale": "Same count as q11_valid_10: 34 valid differences."
    },
    "q11_valid_22": {
      "verdict": "yes",
